const CALLS: Record<string, (...args: any[]) => unknown> = {
  judge: (goal, diagnostics, pageText, review) => judge(goal, diagnostics, pageText, review),
  toPageCheckSteps: (actions) => toPageCheckSteps(actions),
  matchScore: (entry, needle) => matchScore(entry as any, needle),
  normalizeRef: (value) => normalizeRef(value),
  isInspectionGoal: (text) => isInspectionGoal(text),
  buildQaSystemPrompt: (goal) => buildQaSystemPrompt(goal),
  buildQaUserPrompt: (goal) => buildQaUserPrompt(goal),
  buildWrapUpPrompt: (reason) => buildWrapUpPrompt(reason),
  describeScrollPosition: (position) => describeScrollPosition(position),
  formatElement: (element) => formatElement(element),
  formatSnapshot: (result) => formatSnapshot(result),
  diagnosticsCount: (diagnostics) => diagnosticsCount(diagnostics),
};

function render(fn: string, args: unknown[]): string {
  try {
    const text = String(JSON.stringify(CALLS[fn]!(...args)));
    return text.length > 1000 ? `sha256:${createHash('sha256').update(text).digest('hex')}` : text;
  } catch {
    return 'throws';
  }
}

describe('탐색 QA 벡터(옛 TS가 낸 값)', () => {
  it('벡터 수와 함수별 분포', () => {
    expect(VECTORS.length).toBe(718);
    const counts = new Map<string, number>();
    for (const [fn] of VECTORS) counts.set(fn, (counts.get(fn) ?? 0) + 1);
    expect(Object.fromEntries(counts)).toEqual({"judge": 209, "toPageCheckSteps": 104, "matchScore": 52, "normalizeRef": 59, "isInspectionGoal": 189, "buildQaSystemPrompt": 8, "buildQaUserPrompt": 11, "buildWrapUpPrompt": 9, "describeScrollPosition": 47, "formatElement": 5, "formatSnapshot": 10, "diagnosticsCount": 15});
  });

  it.each(VECTORS.map((vector, index) => [index, vector[0], vector[1], vector[2]] as const))('#%i %s', (_index, fn, args, expected) => {
    expect(render(fn, args)).toBe(expected);
  });
});

describe('의도한 차이(옛 TS와 다른 곳)', () => {
  it('짝 없는 서로게이트는 napi 경계에서 U+FFFD가 되어, 이모지 절반으로 찾던 옛 동작과 달리 맞지 않는다', () => {
    // 옛 TS: '😀'.toLowerCase().includes('\ud83d')가 참이라 60점. 새 껍데기: 짝 없는 서로게이트가 U+FFFD가 되어 0점
    expect(matchScore({ name: '😀', text: '', role: '', tag: 'a' } as unknown as RawElement, '\ud83d')).toBe(0);
  });
});
